{% extends "templates/print/ph_basis.html" %}
{% set lieferant = frappe.get_doc("PH Lieferant", doc.lieferant) %}
{% block titel %}Bestellung {{ doc.name }}{% endblock %}
{% block kopfrechts %}<b>Bestellung {{ doc.name }}</b><br>Datum {{ ph_datum(doc.datum) }}{% if lieferant.kundennummer_bei_lieferant %}<br>Unsere Kundennr. {{ lieferant.kundennummer_bei_lieferant }}{% endif %}{% if doc.kommission %}<br>Kommission {{ doc.kommission }}{% endif %}{% endblock %}
{% block inhalt %}
<div class="ph-absender">{{ firma.firmenname }} · {{ firma.strasse }} · {{ firma.plz }} {{ firma.ort }}</div>
<div style="min-height:28mm"><b>{{ lieferant.firmenname }}</b><br>{{ lieferant.strasse or "" }}<br>{{ lieferant.plz or "" }} {{ lieferant.ort or "" }}<br>{{ lieferant.land or "" }}</div>
<h1>Bestellung</h1>
<p>Sehr geehrte Damen und Herren,<br>wir bestellen hiermit zu Ihren uns bekannten Konditionen{% if lieferant.incoterm %} ({{ lieferant.incoterm }}){% endif %}:</p>
<table class="ph-tabelle"><thead><tr><th>Pos.</th><th>Artikelnr.</th><th>Bezeichnung / Ausführung</th><th class="zahl">Menge</th><th>Wunschtermin</th></tr></thead><tbody>
{% for p in doc.positionen if p.status != "Storniert" %}<tr><td>{{ p.idx }}</td><td>{{ p.hersteller_artikelnr or "–" }}</td><td><b>{{ p.bezeichnung }}</b>{% if p.ausfuehrung_text %}<br><span style="color:#6b7280">{{ p.ausfuehrung_text }}</span>{% endif %}{% if p.kommission and p.kommission != doc.kommission %}<br><span style="color:#6b7280">Kommission {{ p.kommission }}</span>{% endif %}{% if p.hinweis %}<br><span style="color:#6b7280">{{ p.hinweis }}</span>{% endif %}</td><td class="zahl">{{ p.menge }} {{ p.einheit or "Stk" }}</td><td>{{ ph_datum(p.wunschtermin) or "–" }}</td></tr>{% endfor %}
</tbody></table>
<h2>Lieferung</h2>
<div class="ph-feld"><b>Lieferadresse</b> {{ (doc.lieferadresse_text or "")|replace("\n", "<br>") }}</div>
{% if doc.wunschtermin %}<div class="ph-feld"><b>Wunschtermin</b> {{ ph_datum(doc.wunschtermin) }}</div>{% endif %}
<div class="ph-feld"><b>Avisierung</b> Bitte Liefertermin vorab per E-Mail an {{ firma.email }} avisieren.</div>
{% if doc.notizen_lieferant %}<p class="ph-hinweis">{{ doc.notizen_lieferant|replace("\n", "<br>") }}</p>{% endif %}
<p>Bitte senden Sie uns Ihre <b>Auftragsbestätigung</b> mit verbindlichem Liefertermin unter Angabe unserer Bestellnummer <b>{{ doc.name }}</b>.</p>
<p>Mit freundlichen Grüßen<br>{{ firma.kurzname or firma.firmenname }}</p>
{% endblock %}

{% extends "templates/print/ph_basis.html" %}
{% block titel %}Wareneingang {{ doc.name }}{% endblock %}
{% block kopfrechts %}<b>Wareneingang {{ doc.name }}</b><br>{{ ph_datum(doc.datum) }}<br>Status {{ _(doc.status) }}{% endblock %}
{% block inhalt %}
<h1>Wareneingangsprotokoll</h1>
<div class="ph-feld"><b>Bestellung</b> {{ doc.herstellerbestellung }}{% if doc.kommission %} · Kommission {{ doc.kommission }}{% endif %}</div>
<div class="ph-feld"><b>Lieferant</b> {{ doc.lieferant }}</div>
<div class="ph-feld"><b>Lieferschein</b> {{ doc.lieferschein_nr_lieferant or "–" }}{% if doc.spediteur %} · {{ doc.spediteur }}{% endif %}{% if doc.packstuecke %} · {{ doc.packstuecke }} Packstücke{% endif %}</div>
<div class="ph-feld"><b>Erfasst von</b> {{ frappe.db.get_value("User", doc.erfasst_von, "full_name") if doc.erfasst_von else "–" }}</div>
<table class="ph-tabelle"><thead><tr><th>Pos.</th><th>Bezeichnung</th><th class="zahl">Erwartet</th><th class="zahl">Erhalten</th><th>Zustand</th><th>Hinweis</th></tr></thead><tbody>
{% for p in doc.positionen %}<tr><td>{{ p.position or p.idx }}</td><td>{{ p.bezeichnung }}{% if p.seriennummer %}<br><span style="color:#6b7280">SN {{ p.seriennummer }}</span>{% endif %}</td><td class="zahl">{{ p.menge_erwartet or 0 }}</td><td class="zahl">{{ p.menge_erhalten or 0 }}</td><td>{% if p.zustand != "ok" %}<span class="ph-test">{{ p.zustand }}</span>{% else %}ok{% endif %}</td><td>{{ p.hinweis or "" }}</td></tr>{% endfor %}
</tbody></table>
{% if doc.reklamation %}<h2>Reklamation</h2><p class="ph-hinweis">{{ (doc.reklamation_text or "Abweichungen siehe Positionen.")|replace("\n", "<br>") }}</p>{% endif %}
{% set fotos = [] %}{% for p in doc.positionen if p.foto %}{% set _ = fotos.append(p.foto) %}{% endfor %}{% for f in doc.fotos %}{% set _ = fotos.append(f.bild) %}{% endfor %}
{% if fotos %}<h2>Fotos</h2><div style="display:flex;flex-wrap:wrap;gap:4mm">{% for f in fotos[:8] %}<img src="{{ f }}" style="width:42mm;height:32mm;object-fit:cover;border:1px solid #d9d4cc">{% endfor %}</div>{% endif %}
<table style="width:100%;margin-top:14mm"><tr><td style="width:50%;padding-right:8mm"><div style="border-top:1px solid #30373e;padding-top:2mm;font-size:8pt">Datum, Unterschrift Wareneingang</div></td><td style="width:50%"><div style="border-top:1px solid #30373e;padding-top:2mm;font-size:8pt">Unterschrift Fahrer / Spediteur (bei Vorbehalt)</div></td></tr></table>
<p class="ph-hinweis">Transportschäden sofort auf dem Frachtbrief vermerken (Vorbehalt) und fotografieren – sonst entfällt der Regress gegen den Spediteur.</p>
{% endblock %}

{% extends "templates/print/ph_basis.html" %}
{% block titel %}AB-Abgleich {{ doc.name }}{% endblock %}
{% block kopfrechts %}<b>Bestellung {{ doc.name }}</b><br>AB {{ doc.ab_nummer or "–" }} vom {{ ph_datum(doc.ab_datum) or "–" }}<br>Status {{ _(doc.status) }}{% endblock %}
{% block inhalt %}
<h1>Prüfprotokoll Auftragsbestätigung</h1>
<div class="ph-feld"><b>Lieferant</b> {{ doc.lieferant }}{% if doc.kommission %} · Kommission {{ doc.kommission }}{% endif %}</div>
<div class="ph-feld"><b>Abweichungen</b> {{ doc.abweichungen_anzahl or 0 }} gesamt, {{ doc.abweichungen_offen or 0 }} offen</div>
<div class="ph-feld"><b>Geprüft</b> {{ frappe.db.get_value("User", doc.ab_geprueft_von, "full_name") if doc.ab_geprueft_von else "–" }} {{ frappe.utils.format_datetime(doc.ab_geprueft_am) if doc.ab_geprueft_am else "" }}</div>
<h2>Positionen (Soll / Ist)</h2>
<table class="ph-tabelle"><thead><tr><th>Pos.</th><th>Bezeichnung</th><th class="zahl">Menge</th><th class="zahl">AB Menge</th><th>Wunschtermin</th><th>AB Termin</th><th>Abweichung</th></tr></thead><tbody>
{% for p in doc.positionen %}<tr><td>{{ p.idx }}</td><td>{{ p.bezeichnung }}{% if p.ausfuehrung_text %}<br><span style="color:#6b7280">{{ p.ausfuehrung_text }}</span>{% endif %}</td><td class="zahl">{{ p.menge }}</td><td class="zahl">{{ p.ab_menge if p.ab_menge is not none else "–" }}</td><td>{{ ph_datum(p.wunschtermin) or "–" }}</td><td>{{ ph_datum(p.bestaetigter_termin) or "–" }}</td><td>{% if p.abweichung and p.abweichung != "keine" %}<span class="ph-test">{{ p.abweichung }}</span>{% else %}–{% endif %}</td></tr>{% endfor %}
</tbody></table>
{% if doc.ab_abgleich %}<h2>Abweichungen und Bewertung</h2>
<table class="ph-tabelle"><thead><tr><th>Pos.</th><th>Feld</th><th>Bestellt</th><th>Bestätigt</th><th>Abweichung</th><th>Bewertung</th><th>Kommentar</th></tr></thead><tbody>
{% for z in doc.ab_abgleich %}<tr><td>{{ z.position }}</td><td>{{ z.feld }}</td><td>{{ z.bestellt }}</td><td>{{ z.bestaetigt }}</td><td>{{ z.abweichung_text or "" }}</td><td>{% if z.bewertung == "ok" %}ok{% elif z.bewertung == "abgelehnt" %}<span class="ph-test">abgelehnt</span>{% else %}<b>{{ z.bewertung }}</b>{% endif %}</td><td>{{ z.kommentar or "" }}</td></tr>{% endfor %}
</tbody></table>{% else %}<p class="ph-hinweis">Keine Abweichungen zwischen Bestellung und Auftragsbestätigung.</p>{% endif %}
{% if doc.ab_hinweis %}<p class="ph-hinweis">{{ doc.ab_hinweis|replace("\n", "<br>") }}</p>{% endif %}
<p style="font-size:8pt;color:#6b7280">Interner Prüfbeleg. Abgelehnte Abweichungen werden dem Lieferanten schriftlich mitgeteilt; ohne Widerspruch gilt die AB als angenommen.</p>
{% endblock %}

{% extends "templates/print/ph_basis.html" %}
{% block titel %}{{ doc.titel }}{% endblock %}
{% block kopfrechts %}{{ doc.marke }}<br>{{ doc.kategorie }}{% if doc.hersteller_artikelnr %}<br>Art.-Nr. {{ doc.hersteller_artikelnr }}{% endif %}{% if doc.stand %}<br>Stand {{ ph_datum(doc.stand) }}{% endif %}{% endblock %}
{% block inhalt %}
{% set bilder = doc.bilder|selectattr("freigabe", "equalto", "erteilt")|list %}
<h1>{{ doc.name_herstellerbezeichnung }}</h1>
<div style="display:flex;gap:8mm">
<div style="flex:1">{% if bilder %}<img src="{{ bilder[0].bild }}" style="max-width:100%;max-height:90mm;object-fit:contain">{% endif %}</div>
<div style="flex:1">
{% if doc.kurz_de %}<p>{{ doc.kurz_de }}</p>{% endif %}
{% if doc.serie %}<div class="ph-feld"><b>Serie</b> {{ doc.serie }}</div>{% endif %}
{% if doc.designer %}<div class="ph-feld"><b>Design</b> {{ doc.designer }}</div>{% endif %}
{% if doc.masse %}<h2>Maße</h2>{% for m in doc.masse %}<div class="ph-feld"><b>{{ _(m.key) }}</b> {{ m.wert }}</div>{% endfor %}{% endif %}
{% if doc.aktueller_preis_cent %}<h2>Preis</h2><div class="ph-feld"><b>{{ doc.preisart }}</b> ab {{ ph_betrag(doc.aktueller_preis_cent, doc.waehrung or "EUR") }} inkl. USt · Stand {{ ph_datum(doc.aktueller_preis_stand) }}</div>{% else %}<h2>Preis</h2><p>Preis auf Anfrage.</p>{% endif %}
{% if doc.lieferzeit_freigegeben and (doc.lieferzeit_text_de or doc.lieferzeit_wochen_bis) %}<div class="ph-feld"><b>Lieferzeit</b> {{ doc.lieferzeit_text_de or (doc.lieferzeit_wochen_von ~ "–" ~ doc.lieferzeit_wochen_bis ~ " Wochen") }}</div>{% endif %}
</div></div>
{% if doc.merkmale %}<h2>Merkmale</h2><ul>{% for m in doc.merkmale %}<li>{{ m.text_de }}</li>{% endfor %}</ul>{% endif %}
{% if doc.ausfuehrungen %}<h2>Ausführungen</h2>{% for g in doc.ausfuehrungen %}<div class="ph-feld"><b>{{ g.gruppe_de }}</b> {{ frappe.get_all("PH Produkt Ausfuehrung", {"produkt": doc.name, "gruppe_key": g.gruppe_key, "status": "Aktiv"}, pluck="name_de", order_by="reihenfolge asc")|join(", ") }}</div>{% endfor %}{% endif %}
{% if bilder|length > 1 %}<h2>Weitere Ansichten</h2><div style="display:flex;flex-wrap:wrap;gap:4mm">{% for b in bilder[1:7] %}<img src="{{ b.bild }}" style="width:52mm;height:40mm;object-fit:cover;border:1px solid #d9d4cc">{% endfor %}</div>{% endif %}
<p style="font-size:8pt;color:#6b7280;margin-top:8mm">Herstellerangaben, Stand {{ ph_datum(doc.stand) or ph_datum(doc.modified) }}{% if doc.hersteller_url %} · Quelle {{ doc.hersteller_url }}{% endif %}. Abbildungen mit Genehmigung des Herstellers. Irrtümer und Änderungen vorbehalten.</p>
{% endblock %}
